{"content":"import { Link, useNavigate } from "@tanstack/react-router";
import { Lock, Menu, Phone, ShoppingCart, User, X, FileText } from "lucide-react";
import { useState } from "react";
import { COMPANY } from "@/data/company";
import { useStore } from "@/lib/store";
import { supabase } from "@/integrations/supabase/client";


import { Logo } from "./Logo";
import { SearchBar } from "./SearchBar";

const NAV = [
  { to: "/products", label: "Products" },
  { to: "/brands", label: "Brands" },
  { to: "/services", label: "Services" },
  { to: "/resources", label: "Resources" },
  { to: "/quote", label: "Request a Quote" },
  { to: "/about", label: "About Us" },
  { to: "/contact", label: "Contact" },
] as const;

export function Header() {
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();
  const { cart, quoteList, session } = useStore();

  /** Admin is always a fresh sign-in: drop any session, then go to the login page. */
  async function goToAdmin() {
    setOpen(false);
    await supabase.auth.signOut();
    void navigate({ to: "/auth", search: { admin: true } });
  }

  const cartCount = cart.reduce((n, l) => n + l.qty, 0);
  const quoteCount = quoteList.reduce((n, l) => n + l.qty, 0);

  return (
    <header className="sticky top-0 z-50 border-b border-border bg-card">
      <div className="bg-navy text-navy-foreground">
        <div className="container-page flex h-9 items-center justify-between text-xs">
          <p className="truncate">{COMPANY.serving}</p>
          <div className="flex items-center gap-4">
            <a href={COMPANY.phoneHref} className="flex items-center gap-1.5 font-semibold hover:text-sky">
              <Phone className="h-3.5 w-3.5" aria-hidden />
              {COMPANY.phone}
            </a>
            <a href={`mailto:${COMPANY.email}`} className="hidden hover:text-sky sm:inline">
              {COMPANY.email}
            </a>
            <button
              type="button"
              onClick={() => void goToAdmin()}
              className="flex items-center gap-1.5 rounded-sm bg-sky px-2 py-0.5 font-semibold text-sky-foreground hover:bg-sky/90"
            >
              <Lock className="h-3.5 w-3.5" aria-hidden />
              Admin
            </button>

          </div>
        </div>
      </div>

      <div className="container-page flex items-center gap-4 py-3">
        <Logo />
        <div className="hidden flex-1 lg:block">
          <SearchBar />
        </div>
        <div className="ml-auto flex items-center gap-1">
          <Link
            to="/quote"
            className="hidden items-center gap-2 rounded-md px-3 py-2 text-sm font-medium text-navy hover:bg-secondary sm:flex"
          >
            <FileText className="h-5 w-5" aria-hidden />
            <span className="hidden xl:inline">Quote</span>
            {quoteCount > 0 && (
              <span className="rounded-full bg-sky px-1.5 text-xs font-bold text-sky-foreground">
                {quoteCount}
              </span>
            )}
          </Link>
          <Link
            to="/account"
            className="flex items-center gap-2 rounded-md px-3 py-2 text-sm font-medium text-navy hover:bg-secondary"
          >
            <User className="h-5 w-5" aria-hidden />
            <span className="hidden xl:inline">{session ? "My Account" : "Sign In"}</span>
          </Link>
          <Link
            to="/cart"
            className="flex items-center gap-2 rounded-md bg-navy px-3 py-2 text-sm font-semibold text-navy-foreground hover:bg-navy-muted"
          >
            <ShoppingCart className="h-5 w-5" aria-hidden />
            <span className="hidden xl:inline">Cart</span>
            <span className="rounded-full bg-sky px-1.5 text-xs font-bold text-sky-foreground">
              {cartCount}
            </span>
          </Link>
          <button
            type="button"
            onClick={() => setOpen((v) => !v)}
            className="rounded-md p-2 text-navy hover:bg-secondary lg:hidden"
            aria-label={open ? "Close menu" : "Open menu"}
            aria-expanded={open}
          >
            {open ? <Menu className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
          </button>
        </div>
      </div>

      <div className="container-page pb-3 lg:hidden">
        <SearchBar />
      </div>

      <nav aria-label="Primary" className="hidden border-t border-border bg-surface lg:block">
        <div className="container-page flex items-center gap-1">
          {NAV.map((item) => (
            <Link
              key={item.to}
              to={item.to}
              activeProps={{ className: "text-sky border-sky" }}
              className="border-b-2 border-transparent px-4 py-3 text-sm font-semibold uppercase tracking-wide text-navy transition-colors hover:text-sky"
            >
              {item.label}
            </Link>
          ))}

        </div>
      </nav>

      {open && (
        <nav aria-label="Mobile" className="border-t border-border bg-card lg:hidden">
          <div className="container-page flex flex-col py-2">
            {NAV.map((item) => (
              <Link
                key={item.to}
                to={item.to}
                onClick={() => setOpen(false)}
                className="flex items-center justify-between border-b border-border py-3 text-sm font-semibold uppercase tracking-wide text-navy last:border-0"
              >
                {item.label}
                <X className="h-0 w-0 opacity-0" aria-hidden />
              </Link>
            ))}
            <Link
              to="/account"
              onClick={() => setOpen(false)}
              className="py-3 text-sm font-semibold uppercase tracking-wide text-navy"
            >
              My Account
            </Link>

          </div>
        </nav>
      )}
    </header>
  );
}
